begin;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-25811','course','Управление персоналом для менеджеров',null,'{"id":"guru-25811","title":"Управление персоналом для менеджеров","shortTitle":"Управление персоналом для менеджеров","coverLabel":"Управление персоналом для менеджеров","description":"Рабочий день менеджера, пятиминутки, коммуникация, продажи, цели и чек-листы.","kind":"course","brand":"90-е","departments":["Руководитель","Зал","Бар"],"positions":["Руководитель","Администратор","Старший бармен"],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Рабочий день менеджера смены.","text":"Миссия менеджера ресторана\n\nМенеджер смены или администратор - это заместитель директора. Самое главный человек в заведении в отсутствие Управляющего. Задача администратора в том, чтобы в отсутствие топ-менеджеров ресторан работал еще лучше, чем тогда, когда они на месте. Хороший администратор отличается от плохого тем, что именно он ведет смену в правильном направлении, а не наоборот.\n\nМиссия администратора:\n\nБыть проводником и амбассадором ценностей ресторана для гостей и сотрудников.\n\nОсновные задачи администратора:\n\nВедение смены в ресторане с помощью установленных инструментов и обратная связь сотрудникам по ним.\nНабор и обучение линейного персонала для зала (официантов, барменов, барист, хостес).\nВедение кассовой документации и ответственность за кассовую дисциплину.\nВедение ежедневной и еженедельной документации.\nКонтроль закупок.\nВыполнение поручений своих руководителей.\n\nДля того, чтобы было проще, понятнее и удобнее выполнять свои обязанности, у нас есть все необходимые инструменты: четкий распорядок дня для администратора, чек-листы ведения смены, открытия и закрытия заведения и график еженедельных встреч с сотрудниками и руководителями для отчета по результатам работы.\n\nРасписание рабочего дня администратора.\n\n*В примере ниже рабочий день в ресторане начинается в 8:00. Аналогичным образом график переставляется под любое время старта.\n\n1) Рабочий день менеджера смены начинается в 7:45. Твоя задача - проконтролировать, что все сотрудники пришли на работу к 8:00 вовремя. Приход в 8:01 - уже опоздание. За него может полагаться штраф или выговор. Но не забудь похвалить тех, кто пришел вовремя :) Важно: бесполезно требовать пунктуальности от своих сотрудников, если сам менеджер не является в этом примером.\n\n2) С 8:00 до 8:45 твоя задача принять кассу с предыдущего дня и проконтролировать заполнение чек-листа. Смотри, чтобы и бар, и зал, и кухня действительно работали с чек-листами, а не просто ставили галочки по факту. Правильно и вовремя заполненный чек-лист поможет учесть каждый важный момент при открытии, а также вовремя отреагировать на неполадки. Отнесись к этому серьезно!\n\n3) В 8:45 все три чек-листа открытия и два чек-листа заготовок и полуфабрикатов должны быть у тебя. Если хоть одно подразделение опаздывает с чек-листом - непременно дай обратную связь.\n\n4) В 8:55 проведи пятиминутку с сотрудниками.\n\n5) С 8:45 до 9:15 ты проверяешь чек-листы и реагируешь:\n\nДаешь обратную связь ответственным за заполнение. Не забудь похвалить, если все сделано правильно и вовремя;\n\nЗаказываешь товары и продукты;\n\nРаздаешь поручения по уборке;\n\nЕсли что-либо сломано - вызываешь ремонт;\n\nЕсли пришло время техобслуживания - вызываешь сервис.\n\n6) В 9:00 ресторан должен открыться для гостей. Твоя задача сделать так, чтобы в 8:55 абсолютно все было готово к открытию.\n\n7) С 9:00 до 12:00 у тебя есть время, чтобы заняться поручениями от руководителей и документацией. Также рекомендую именно в это время делать объемные рутинные задачи - составление графика работы, переговоры с поставщиками, мониторинг цен на необходимые товары. Это наиболее благоприятное время, так как все контрагенты в это время готовы общаться, а голова еще свежая. Старайся полностью выполнять хотя бы три объемных задачи в день.\n\n8) С 12:00 до 16:00, во время наплыва гостей и ланча, ты координируешь работу своих сотрудников и по ходу работы заполняешь первый чек-лист работы сотрудников зала на смене.\n\n9) В 16:00 происходит пересменка в баре и в зале. Твоя задача - проконтролировать приход вечерних сотрудников вовремя. В 16:00 они должны быть уже в зале, а приход в 16:01 уже считается опозданием. За него полагается штраф или выговор. Обязательно похвали тех, кто пришел вовремя!\n\n10) С 16:00 до 18:00 ты занимаешься HR делами бара.\n\nИщешь сотрудников, если их не хватает - обзваниваешь резюме;\nСоставляешь график работы;\nАнализируешь чек-листы обслуживания за предыдущий день;\nГотовишься к тренингам или собраниям;\nПроводишь индивидуальные встречи с сотрудниками, ставишь им цели, даешь обратную связь по результатам работы.\n\n    11) С 18:00 до последнего гостя твой основной фокус направлен на гостей.\n\nОбщаешься с гостями, встречаешь и провожаешь их;\nПомогаешь официантам;\nСобираешь у гостей обратную связь о блюдах и напитках.\n\n    12) С 18 до 20 твоя задача заполнить второй чек-лист обслуживания за смену, дать по нему обратную связь.\n\n    13) В 22:00 начинается закрытие кассы (промежуточное, не всегда совпадает с закрытием ресторана). Твоя задача его проконтролировать и принять работу. Поблагодари официантов за смену и отпусти часть ребят домой - это снизит расходы на такси, и сэкономит часы сотрудников. Проконтролируй заполнение чек-листов закрытия на баре и в зале.","images":["assets/remaining-courses/guru-25811-42948-0.jpg","assets/remaining-courses/guru-25811-42948-1.jpg","assets/remaining-courses/guru-25811-42948-2.jpg"],"links":[],"id":"42948"},{"title":"Делаем рутинное интересным: Проведение пятиминуток","text":"Проведение пятиминуток\n\nПятиминутка — обязательное собрание персонала смены перед открытием. Собрания-пятиминутки проводят перед началом смены, это очень эффективно и плодотворно влияет на работу персонала. Эти плановые совещания многие ошибочно считают бесполезными. На самом деле, без них никак, они способствуют поддержанию дисциплины и способны зарядить всю смену хорошим настроением и важной информаций. Как следует из названия, пятиминутка должна длиться 5 минут, и еще 3-5 минут на решение вопросов команды. Есть несколько важных правил, как провести пятиминутку так, чтобы это было интересно и эффективно.\n\nНачинайте совещание всегда вовремя – показывайте положительный пример. Вообще, это работает для любых мероприятий - учтите, ваши сотрудники берут пример с вас!\nПроводите совещание стоя – таким образом пятиминутка не будет перерастать в пару часов горячих споров, зачастую совсем не конструктивных и не по теме\nНе поднимайте вопросы которые решаются в рабочем порядке, без привлечения всех участников совещания (время – деньги)\nСоблюдайте правила приличия – зевания или явное показное безразличие – не способствует плодотворному общению\n\nАлгоритм проведения пятиминутки должен быть таким:\n\n1) Всегда начинаем с хорошей новости. Пусть каждый сотрудник поделится чем-то добрым. Может, он недавно ходил на крутую выставку, или, на крайний случай, просто выспался. \n\n2) Озвучиваем выручку и чай за предыдущий день. Это важно! Дайте ребятам почувствовать свою причастность к финансовым результатам! Хвалим всю смену, если цель выполнена.\n\n3) Озвучиваем цель по выручке на текущий день. Нельзя упускать этот момент! Каждый член команды должен чувствовать себя ответственным за результаты совместной работы. Цель для них должна быть реалистичной, но при этом амбициозной. Дайте сотрудникам пару советов, как можно достичь этой цели.\n\n4) Озвучиваем стоп-листы по всем позициям, если они есть. Это обязательно! Согласитесь, официант, который не в курсе, каких блюд сегодня в ресторане нет, выглядит перед гостем совсем невыгодно.\n\n5) Озвучиваем меню бизнес-ланча, если оно меняется. Хорошей практикой будет провести небольшой блиц - спросить ингредиенты того или иного блюда из ланча у официантов. Это не займет много времени, не сильно загрузит, не испортит настроение команде. А те ребята, которые знают меню хуже, смогут послушать более подготовленных коллег.\n\n6) Рассказываем о том, какие есть резервы столов на день.\n\n7) Распределяем ребят по позициям в зале. Даем задания на день.\n\n8) Желаем всем отличной смены\n\nВведите собственные традиции для пятиминуток - поставьте на общий стол вкусное печенье или шоколадку, кофе или чай для всех, анекдоты или планы на выходные. Сделайте эти 5 минут не рутиной, а приятным началом рабочего дня :)","images":["assets/remaining-courses/guru-25811-42949-0.jpg","assets/remaining-courses/guru-25811-42949-1.jpg","assets/remaining-courses/guru-25811-42949-2.jpg"],"links":[{"title":"Видео к уроку","url":"https://www.youtube.com/embed/MMV2vB8FcZc?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25811%2Flesson%2F42949&aoriginsup=1&vf=1"}],"id":"42949"},{"title":"Менеджер - младший HR в заведении","text":"Интервью для кандидата на должность официанта/бармена.\n\nВот вам очень полезый инструмент - список вопросов для кандидата на собеседовании. Вы можете взять его и адаптировать под свой ресторан, добавив несколько вопросов, которые важны и принципиальны именно вам.\n\nЭто те вопросы, которые вы задаете сами (!!!) на интервью. Это не письменная анкета! Вам нужно видеть, как кандидат общается и отвечает на вопросы.\n\nУниверсальный профайл сотрудника ресторана:\n\nулыбчивый\nгостеприимный\nс чувством юмора\nответственный\nпунктуальный\nориентирован на гостя\nумеет вкусно говорить\nаккуратный\n\n***Сначала внимательно посмотрите на кандидата. Он пришел вовремя? Если нет, то вы уже можете сделать вывод о его пунктуальности. Если он одет аккуратно, от него приятно пахнет, он приветлив - это очень хорошие признаки. Если нет - то это в первую очередь неуважение к вам. Задумайтесь.\n\n***Смотрите на то, как кандидат себя ведет. Нам нужны улыбчивые, раскованные ребята, но не все смогут расслабиться на первом собеседовании. Тут можно немного помочь, пошутить, разрядить обстановку. Или наоборот, сохранять холодный неприступный вид и смотреть, как будет реагировать кандидат - будет-ли пытаться расположить вас к себе.\n\nРасскажите о себе то, что считаете нужным.\n\nКомментарий: обращайте внимание на рассказ. Задавайте наводящие вопросы. Если человек рассказывает только сухие факты - работал там-то, учился там-то, непременно спросите про хобби, увлечения. Выведите на положительную эмоцию. Следите за тем, как человек рассказывает об увлечениях: если без единой эмоции и сухо, значит, нам этот кандидат, скорее всего, не подходит. Если он о любимом занятии рассказывает сухо и без энтузиазма, он не сможет вкусно продать наши напитки и кухню. Также по хобби можно увидеть, командный перед вами игрок или одиночка.\n\n2. Расскажите о своем опыте работы. Если нигде не работал, спрашивайте про учебу.\n\nКомментарий: тут смотрим на то, как именно рассказывает. Можно попросить его описать свой рабочий день. Описывает тщательно и последовательно? Перед вами человек порядка. Описал двумя-тремя фразами или растерялся? Человек не системный. Для официанта или бармена это не всегда плохо. Смотрите на общее впечатление. \n\n3. Причина увольнения с прошлого места.\n\nКомментарий: вот разные причины.\n\n- конфликт с руководством. Просите подробно описать конфликт. Для вас это маркер того, что человек конфликтен. Разберитесь в ситауции, кто на самом деле был прав, а кто виноват. Попросите кандидата описать своего идеального руководителя.\n\n- мало денег. Непременно спросите, а сколько бы он хотел зарабатывать. Именно цифра! И почему не смог на предыдущем месте. Подумайте вместе с кандидатом, а у вас он сможет столько заработать? Если да, то за сколько времени, сколько смен, и так далее.\n\n- захотел сменить обстановку. Нормальная причина. Тут следует спросить, что именно он ждет от нового места работы.\n\n4. Какое ваше любимое блюдо/коктейль? Расскажите мне о нем так, чтобы я захотела его попробовать.\n\nКомментарий: Простой тест на профпригодность - умеет-ли человек говорить о еде. Не надо помогать кандидату отвечать на вопрос! Не отвечает? Мнется и не может рассказать? Повод задуматься.\n\n5. Расскажите о вашем последнем положительном опыте посещения кафе/бара.\n\nКомментарий: Тест на понимание кандидатом гостеприимства и клиентоориентированности. Тест на ценности кандидата! Он сам вам перечислит то, что для него важно в ресторане. Не отвечает? Помогите! Хоть Макдональдс! Где было вкусно, быстро, вежливо? Что именно запомнилось? Почему хотите вернуться?\n\nКейс на клиентоориентированность: У гостя разрядился мобильный. Он просит вас помочь.\n\nКомментарий: Клиентоориентированный человек побежит искать зарядку, розетку, даст свой зарядник. Другой кандидат ответит в стиле “а я что могу сделать?”\n\n6. Расскажите о вашем последнем негативном опыте посещения кафе/ресторана.\n\nКомментарий: Где было долго, грубо, невнимательно, обсчитали, забыли заказ…\n\nТак вы увидите, какие пункты кажутся важными кандидату, на что он сам будет обращать внимание. Опять тест на ценности!\n\n7. Почему люди опаздывают?\n\nКомментарий: ответ на этот вопрос помогает выяснить отношение кандидата к опозданиям: ищет-ли он оправдание, считает-ли, что опоздания - нормальная практика.\n\n8. Кейс: Ваш коллега постоянно опаздывает на общую с вами смену. Каковы ваши действия?\n\nВаш сменщик систематически оставляет после себя грязное рабочее место. Ваши действия?\n\nКомментарий: такие кейсы помогают увидеть, будет-ли кандидат давать обратную связь руководству, коллегам, или будет молчать, или мстить. Это способ выявить его уровень ответственности.\n\nОбучение и развитие сотрудников\n\nНа администраторе лежит функция обучения и развития как новых, так и давно работающих сотрудников. Это, пожалуй, самая ответственная часть нашей работы.\n\nДумаю, каждый согласится с тем, что мы обязательно должны дать знания новым сотрудникам. Но что вкладывается в это понятие - обучение? Дать вызубрить меню? Или оставить в покое - пусть сам выплывет, если сильный?\n\nНа самом деле нет) Мы должны стать самыми настоящими наставниками и коучами для своих новичков. Хорошо, что сейчас появился такой инструмент как СервисГуру - можно больше не распечатывать тонну ненужной бумаги для изучения, а просто дать сотруднику доступ в приложение. Здорово, что у нас появилось свободное время! Посвятим его общению со своими ребятами.\n\nНе забывай, что первые рабочие дни в ресторане - самые сложные и нервные для стажеров. Будь рядом с ними в эти непростые моменты.\n\nЗапомни простые правила наставника в ресторане:\n\nВ самый первый рабочий день сотрудника ты должен быть с ним почти постоянно. Обязательно нужно:\n\nПоказать ресторан. Не только залы, но и стафф-зону, раздевалку, служебный туалет. Показать, где можно поесть и попить чаю. Познакомить с коллегами.\nРассказать правила внутреннего распорядка. Ко скольки нужно приходить, во сколько можно уходить, у кого отпроситься на перекур. Упомянуть все сложные дисциплинарные моменты. А потом - задать пару-тройку наводящих вопросов, чтобы удостовериться, что сотрудник все понял.\nПознакомить с программой стажировки и озвучить, сколько эта стажировка будет длиться по времени. Непременно рассказать и показать, что будет являться результатом этой стажировки! После убедиться, что сотрудник все понял - задайте пару вопросов.\nПервый день должен запомниться! Ведь у нас не будет второго шанса произвести первое впечатление. Помни, впечатление сотрудника складывается в течение первых 2,5 часов. Если мы успеем разочаровать его за это время - момент будет упущен.\nПозаботься о том, чтобы у вас был интересный увлекательный материал в SeviceGuru об истории и ценностях компании. В первый день дать стажеру посмотреть классное видео от создателя и послушать о ценностях - лучшая практика!\nПосле первого дня непременно сядьте вместе со стажером и обсудите, что ему понравилось, что он бы хотел изменить в работе. Не забывай, во время стажировочного периода ты обязан общаться с новым человеком минимум один раз в день!\nОбратная связь. Это словосочетание должно стать твоим девизом! Хвали за правильные действия, давай объективную критику за неверные. Только так, с помощью постоянной (пусть даже немного навязчивой) обратной связи сотрудник сможет выработать правильные привычки.\n\nОбучение сотрудников - важная часть нашей с вами работы. Главный инструмент обучения для вас - личный пример. Ты должен стать образцом идеального выполнения стандартов и рутин. Помни, три основных принципа успешной и взаимовыгодной стажировки - четко прописанная программа со сроками, наставничество и обратная связь. Удачи тебе и твоим стажерам!\n\nПример стажировочного листа официанта, бармена\nСтажировка нового сотрудника должна включать в себя изучение материала в ServiceGuru, проверку знаний каждую смену и обязательно устные опросы по изученному.\n\nСтажировка бармена\n\nДень 1. Пробный. С 12:00 до 20:00. Длительность 8 часов.\n\nАдминистратор проводит экскурсию по ресторану.\nБеседа с администратором. Рассказ о ценностях и главных принципах работы заведения. Демонстрация меню для гостей.\nВыдать доступ в приложение. Предложить изучить материалы по истории и ценностям ресторана. После прочтения дать возможность пройти тест и задать вопросы:\nЧто ты прочитал?\nКакая миссия у нашего ресторана?\nКакие основные продукты в нашем ресторане?\nКакие у нас стандарты внешнего вида?\n\n4. Показать барные чек-листы. Объяснить, зачем они.\n\n5. Запустить в бар. Бармен показывает: устройство бара, хранение продуктов, как выглядит подготовка к смене.\n\n6. Выдаем ТТК по заготовкам. Объясняем спорные моменты.\n\n7. Стажер проводит время до 19:00 с барменом, помогает.\n\n8. В 19:30 общается с администратором. Задать вопросы:\n\nКак тебе у нас в баре?\nЧто понравилось?\nЧто бы ты изменил?\n\n9. Админ дает обратную связь по первому дню. Если принято решение работать дальше, тогда на дом выдается книга стандартов бармена+ТТК заготовок.\n\nДомашнее задание: выучить ТТК по самым ходовым ПФ. (Отметить их в его распечатке!)\n\nДень 2. Длится полную смену. Начало в 12:00\n\nС утра стажер помогает с открытием бармену, учится заполнять чеклист с инструкцией из ServiceGuru.\nСтажер делает ПФ вместе с барменом.\nДнем беседует с администратором. Рассказывает ТТК по выученным заготовкам. Если выучил хорошо - хвалим. Если плохо - даем серьезную конструктивную обратную связь. Но не гнобим :)\nСтажер помогает бармену во всех его делах.\nПосле смены обмен обратной связью.\nКак тебе смена с _____ (имя бармена-наставника)?\nЧто тебе понравилось?\nКакие коктейли сегодня делал?\nСложно тут работать?\n\n    6. Домашнее задание: выучить ТТК по 10-и Классическим коктейлям.\n\nДень 3. Полная смена.\n\nС утра заполняет чек-листы самостоятельно (открывает смену)\nСам пишет список продуктов, решает, какие делать ПФ на смену. Бармен и администратор дают обратную связь.\nДнем рассказывает админу ТТК 10 выученных коктейлей. Все ок - хвалим. Не ок - конструктив.\nДомашнее задание - выучить оставшиеся классические коктейли\nДо конца смены работает вместе с барменом, чек-лист закрытия заполняет сам под контролем бармена.\nОбратная связь с админом.\n\nДень 4.\n\nРабота всю смену с барменом, максимум самостоятельности.\nПроверить ДЗ. Дать новое: выучить авторские коктейли.\nРассказать про особенности меню кухни. Дать изучить, показать пример, что можно предложить к напиткам за стойкой.\nНазначить дату аттестации. Рассказать, что на ней будет происходить.\n\nДень 5. Аттестация:\n\nБлок “о ресторане”\nРасскажи о нашей концепции?\nКакая наша миссия?\nВ чем наша фишка?\nКак можно сделать гостя счастливее, какие у нас есть инструменты? (скидки, комплименты, отличный вкус блюд)\n\n      2. Крепкий алкоголь:\n\nНазови, какие у нас есть бурбоны\nНазови, какие у нас есть виноградные дистилляты\nКакая у нас есть водка?\n\n      3. Авторские напитки:\n\nНазови ТТК 5 Классических коктейлей на твой выбор\nНазови 5 авторских на твой выбор\n\n      4. Еда.\n\nЧто предложишь на закуску к коктейлям? (на выбор)\nНа закуску к пиву?\nОпиши одно любое блюдо из меню.\n\nКритерии:\n\nотвечает четко, бойко, с юмором, все знает - отлично\nотвечает бойко, не помнит половину ингредиентов, но хорошо и артистично выкручивается - хорошо\nотвечает вяло, без интереса, знает плохо - плохо. Спроси причину, почему так плохо подготовлен. Назначь повторную аттестацию. Если не сдаст и ее - увольняем.\n\nСтажировка официанта\n\nДень 1. Пробный. С 12:00 до 20:00. Длительность 8 часов.\n\nМенеджер проводит экскурсию по бару.\nБеседа с менеджером. Рассказ о том, что у нас за заведение, о его ценностях и главных принципах. Демонстрация меню для гостей.\nДать доступ в ServiceGuru. Предложить прочитать при вас Вводный курс - о Компании. После прочтения задать вопросы:\nЧто ты прочитал?\nКакая миссия у нашей компании?\nКакие основные продукты у нас в ресторане?\nКакие у нас стандарты внешнего вида?\n\n4. Показать чек-листы зала. Объяснить, зачем они.\n\n5. Запустить в зал, приставить к опытному официанту. Он показывает: устройство зала,где и что лежит, как выглядит подготовка к смене.\n\n7. Стажер проводит время до 19:00 с официантом, помогает.\n\n8. В 19:30 общается с администратором. Задать вопросы:\n\nКак тебе у нас в ресторане?\nЧто понравилось?\nЧто бы ты изменил?\n\n9. Менеджер дает обратную связь по первому дню. Если принято решение работать дальше, тогда на дом выдается задание учить стандарты в ServiceGuru, дается задание выучить первые простые разделы меню.\n\nДень 2. Длится полную смену. Начало в 12:00\n\nС утра стажер помогает с открытием официанту, учится заполнять чек-лист с инструкцией из ServiceGuru.\nСтажер готовит зал вместе с официантом.\nОбъясняем стажеру стандарты обслуживания. Задаем вопросы:\nКак мы можем поприветствовать гостя?\nКогда мы подаем комплимент от шефа? В любом случае подаем или нет?\nКогда и как можно предложить гостю доп. блюда? Как предлагаем?\nКакие особые блюда мы можем предложить гостю?\nДнем беседует с менеджером. Рассказывает выученные блюда. Если выучил хорошо - хвалим. Если плохо - даем серьезную конструктивную обратную связь. Но не гнобим :)\nСтажер помогает официанту во всех его делах.\nПосле смены обмен обратной связью.\nКак тебе смена с _____ (имя официанта-наставника)?\nЧто тебе понравилось?\nКакие блюда сегодня видел?\nСложно тут работать?\n\n    6. Домашнее задание: выучить горячие блюда и салаты.\n\nДень 3. Полная смена.\n\nС утра заполняет чек-листы самостоятельно (открывает смену)\nДнем рассказывает менеджеру или наставнику выученные блюда. Все ок - хвалим. Не ок - конструктив.\nДомашнее задание - выучить 10 классических коктейлей.\nДо конца смены работает вместе с официантом, чек-лист закрытия заполняет сам под контролем менеджера/наставника.\nОбратная связь с менеджером.\n\nДень 4.\n\nРабота всю смену с официантом, максимум самостоятельности.\nПроверить ДЗ. Дать новое: выучить оставшиеся коктейли.\nНазначить дату аттестации. Рассказать, что на ней будет происходить.\n\nАттестация:\n\n1 блок: Алкоголь\n\nЧто из напитков предлагаем гостям, которые у нас впервые?\nКакие сорта пива у нас есть?\nЧто такое бурбон? Какие у нас есть сорта?\nЧто такое single malt?\nКакие у нас есть авторские коктейли?\n\n2 блок: Стандарты. Ролевая игра - обслуживание стола. (Придумать сценарий!)\n\n3 блок: Меню. Спросить рандомно 10-15 блюд.\n\nКритерии оценки:\n\nрассказывает бойко, живо, вкусно, хорошо знает ответы - отлично\nрассказывает вкусно, но иногда забывает блюда и ингредиенты - хорошо\nрассказывает бойко, но не то :) - плохо. Переаттестация!\nрассказывает вяло, не знает ответов - очень плохо. Нам такой нужен?","images":["assets/remaining-courses/guru-25811-42950-0.jpg","assets/remaining-courses/guru-25811-42950-1.jpg","assets/remaining-courses/guru-25811-42950-2.jpg","assets/remaining-courses/guru-25811-42950-3.jpg"],"links":[{"title":"Видео к уроку","url":"https://www.youtube.com/embed/IIFBfYy5mtc?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25811%2Flesson%2F42950&aoriginsup=1&vf=1"}],"id":"42950"},{"title":"Коммуникация с сотрудниками на смене.","text":"Обратная связь.\n\nПринято считать, что необходимо всегда указывать человеку на его проступки, а хвалить его не нужно - это пустое сотрясание воздуха. Это миф!\n\nАмериканские ученые проводили интересный эксперимент. Разделили контрольную группу студентов на две команды и дали им одинаковое задание. Но первую команду в ходе эксперимента часто хвалили, постоянно давали обратную связь - близко-ли она к цели, и кормили вкусными шоколадными кексами. При этом, со второй командой никто не разговаривал, не хвалил и не направлял. С ними работали молча и кормили реедиской. Результаты поразительные! Первая команда сделала свое задание за 2 часа, при этом вторая - за 8! Видите, как действует похвала и обратная связь на результативность?\n\nСегодня мы поговорим о том, как давать обратную связь правильно.\n\nСначала о позитивном. Что может быть проще - хвалить? Но даже тут есть тонкости.\n\nХвалить нужно своевременно. То есть, сразу как только вы заметили, что человек совершил то или иное правильное действие.\nХвалить нужно лично! Упоминайте имя человека.\nХвалите за конкретное дело, а не за личные качества.\nХвалить нужно при всех. Так похвала будет мотивировать остальных сотрудников.\n\nТеперь о конструктивном -  никто не говорил, что такая обратная связь не нужна.\n\nВ работе с линейным персоналом отлично работает метод сэндвича:\n\nПозитив-конструктив-позитив\n\nПример: Вася, у тебя отлично получается общаться с гостями, и ты станешь еще эффективнее, когда начнешь записывать заказы в блокнот и перестанешь забывать позиции. Мне кажется, у тебя все получится!\n\nВидите, вы вроде и раскритиковали Васину забывчивость, но так, что никому не обидно)\n\nДля конструктивной обратной связи тоже есть свои правила:\n\nКритиковать нужно своевременно. То есть, сразу как только вы заметили, что человек совершил то или иное неправильное действие. Только тогда у человека выработается нужный рефлекс.\nКритиковать нужно конкретный поступок, а не личность человека.\nКритиковать нужно так, чтобы не обидеть, но дать понять, что ему есть куда меняться.\nКритиковать нужно один на один.\n\nЗапомните, обратная связь - один из самых важных инструментов вашей работы. Обратной связи много не бывает! Хвалить, благодарить и признавать своих сотрудников также важно, как и указывать на их ошибки.\n\nВстречи по развитию с сотрудниками.\n\nС каждым сотрудником ресторана еженедельно должна проводиться встреча. Это встречи по личному развитию. Дата и тема встречи должна быть известна сотруднику заранее, лучше всего за 7 дней, то есть на каждой встрече вы назначаете дату новой встречи. Эти встречи должны мотивировать и воздействовать на лояльность сотрудника. Нужны для обсуждения хода выполнения предыдущих личных целей, постановки новых. На каждой встрече тебе понадобится определенный набор инструментов и метрик, чтобы встреча с сотрудником отличалась от простой рабочей беседы.\n\nИнструменты:\n\nЧек-листы работы на смене, открытия, закрытия - за всю неделю.\nОтчеты по выручке и среднему чеку с разбивкой по официантам.\nОтзывы в социальных сетях и в книге отзывов.\n\nС помощью чек-листов ты сможешь восстановить картину каждой смены определенного сотрудника и отследить его эффективность, с помощью отчетов по выручке ты сможешь сделать выводы о том, владеет ли сотрудник техникой продаж, а с помощью отзывов ты можешь показать ему обратную связь от гостей о его работе. Находим отзывы за каждую смену этого сотрудника и совместно их анализируем.\n\nНа встрече:\n\nДается обратная связь по работе на сменах. Она дается исходя из отчетов, метрик и наблюдений, а не исходя из личного отношения к сотруднику! Внимание! Давая обратную связь, не забывай упоминать сначала положительные стороны, потом области для развития!\nСтавится личная цель - по выручке, по продажам, по введению новых блюд, другие цели.\nОбсуждается ход выполнения предыдущей цели.\nПоблагодари сотрудника за что-то конкретное или просто за работу.\n\nТакие же встречи должны устраивать с администратором управляющие заведения!\n\nВстреча должна быть неформальной, но сотрудник должен понимать, что это не просто беседа, а рабочий процесс. У тебя должен быть четкий график встреч. Сотрудники должны быть в курсе встречи заранее, минимум за день. Идеально, если у тебя заранее есть график встреч на всю неделю.\n\nЭти встречи нужны для того, чтобы делегировать задачи, чтобы постоянно держать сотрудников в курсе дела, управлять их вовлеченностью. Ставь интересные для них цели, давай развивающие задания, делегируй полномочия. Не знаешь, какую цель поставить? Спроси его самого. Может быть, он хочет ввести в меню новый коктейль. Или найти нового выгодного поставщика. Или побить рекорд по выручке. Пусть это будет цель, которая замотивирует вас обоих! В конце месяца по результатам выполнения целей можно дарить подарки/давать премию.\n\nПример встречи по развитию. :\n\nВася - мифический официант.\n\nКак твои дела, Вася? (Несколько личных, дружеских вопросов, если это уместно. Нужно разрядить обстановку)\nВася, давай посмотрим, как ты отработал неделю. Смотри, вот это те чеклисты, которые я заполнял на тебя по обслуживанию. У тебя очень круто получаются доп. продажи! Класс, так держать! Ты лидируешь! Тебе нужно немного подтянуть дисциплину. Ты три раза из пяти забыл повторить заказ. Да, я верю, что у тебя хорошая память, но гости часто сами забывают, что они заказали. Повторять нужно, чтобы подстраховать себя. Как тебе с этим помочь?\nТвоя предыдущая цель - личный средний чек 1000 рублей. Ты крут, у тебя получилось!\nСможешь за эту неделю продать 20 ВИП-коктейлей? А сколько сможешь? 15? Давай тогда поставим тебе цель продать 15 ВИП коктейлей.\nА еще, спасибо тебе, Вася, что помог обучить стажера Федю. Из тебя получился хороший наставник.","images":["assets/remaining-courses/guru-25811-42951-0.jpg","assets/remaining-courses/guru-25811-42951-1.jpg","assets/remaining-courses/guru-25811-42951-2.jpg"],"links":[],"id":"42951"},{"title":"Роль менеджера в построении продаж в ресторане","text":"Менеджер смены играет самую непосредственную роль в построении продаж в ресторане!\n\nВо первых, именно его функция - контроль выполнения стандартов каждым из сотрудников на смене и обратная связь по ним. Для того, чтобы контролировать стало проще и появился инструмент измерения эффективности, я рекомендую заполнять чек-лист работы на смене на каждого из официантов минимум 1 раз в смену. Для того,чтобы его заполнить, нужно просто внимательно наблюдать за тем, как работает с гостями каждый официант. А это и есть ваша основная задача. Сразу после заполнения чек-листа обязательно дать обратную связь сотруднику. Похвалить за те пункты, по которым стоят плюсы, обсудить пункты, которые не удались по той или иной причине. Проговорить с сотрудником важность каждого из этих пунктов.\n\nВот вопросы для чек-листа обслуживания на смене. Данный чек-лист должен заполняться администратором на каждого официанта минимум раз в день. Он проверяет соблюдение стандартов. По результатам обязательно даем обратную связь.\n\nПриветствие, подача меню\nПредложение напитка при подаче меню\nРассказ о спешл-блюдах и напитках, рекомендация\nПрием заказа, только письменно!\nДополнительная продажа\nПовторение заказа\nНазвано время ожидания\nСервировка стола\nПодача блюд\nПоследующий уход за столом\nРассказ о системе лояльности\nРасчет гостей\nТеплое прощание с гостем\n\nВо вторых, ваша задача - обучение сотрудников! Нужно научить ребят в ресторане быть профессионалами в продажах!\n\nПроверьте, знают ли они основы построения продаж? Если нет, расскажите им, устройте мини-тренинг с последующей отработкой.\n\nМотивация персонала\n\nВажная задача менеджера смены - мотивация к действию! Я рекомендую вам ежедневно подстегивать и мотивировать вашу команду продавать больше. Как это сделать? В час пик распечатайте отчет по продажам за текущий день. На этом же листе напишите цель на день, которую вы ставили на пятиминутке, и сумму, которой недостаточно для ее выполнения. Вот и новая цель! На этом же листе можно выписать официантов-лидеров по выручке и среднему чеку. А остальным предложить догнать и обогнать лучшие результаты. Это очень простой и действенный способ поднять настроение и внушить азарт всей команде.\n\nРасчет ежедневной выручки\n\nОбучение персонала, общение с гостями, соблюдение стандартов, в конечном итоге направлены на одно - увеличение продаж. В работе менеджера – это приоритетное направление.\n\nКакие же существуют возможности увеличения продаж?\n\nДля начала следует понимать, что отследить увеличение или снижение продаж мы можем по выручке ресторана.\n\nВЫРУЧКА = КОЛИЧЕСТВО ГОСТЕЙ * СРЕДНИЙ ЧЕК ГОСТЯ\n\nЭто самая простая формула расчета, которая отражает суть вопроса.\n\nРассмотрим увеличение продаж при том же количестве гостей, т.е. с помощью увеличения среднего чека.\n\nПомните:\n\nЦель - увеличение среднего чека, перед персоналом не ставится!\n\nПерсоналу нужные более конкретные цели!\n\nУстановить финальную сумму, к которой должен прийти сотрудник по окончании смены.\nНеобходимо поставить цель, эффект от которой можно ощутить через час, два, максимум к концу смены.\nДать готовый рецепт по выполнению данной цели.\n\nЛюбой процесс начинается с планирования. В ресторане отправной точкой и итогом всегда служит Бюджет.\n\nМетодика расчета ежедневной выручки ресторана.\n\n﻿Основная идея данного метода заключается в том, что в каждом ресторане разбивка выручки по дням недели в процентном отношении всегда стабильна. Зная процентное соотношение выручки по дням недели, вы можете рассчитать необходимую планируемую выручку на каждый день.\n\nПосле расчета выручки по дням недели и определения цели на день ее следует распределить на персонал.\n\nПринцип распределения выручки схож в большинстве ресторанов, выручка разбрасывается между вечерней и утренней сменой в соотношении - 1/3 утренняя смена, 2/3 вечерняя. После этого цель распределяется между официантами, работающими в смене.\n\nНа этом этапе следует учесть, что в реальности уровень подготовки персонала может довольно сильно разниться. Поэтому индивидуальные цели следует корректировать с учетом навыков продаж каждого сотрудника.\n\nПомните о том, что сотрудники перестают идти к поставленной цели в двух случаях:\n\nЦель слишком легка, не нужно никаких усилий для ее выполнения\nЦель нереальна, как ни напрягайся, все равно не достать.","images":["assets/remaining-courses/guru-25811-42952-0.jpg","assets/remaining-courses/guru-25811-42952-1.jpg","assets/remaining-courses/guru-25811-42952-2.jpg","assets/remaining-courses/guru-25811-42952-3.jpg"],"links":[],"id":"42952"},{"title":"Лучшая практика для выполнения плана по продажам.","text":"Проведение конкурсов среди персонала.\n\nАкции и конкурсы - отличный инструмент, чтобы достигать амбициозных целей по выручке! Сейчас мы говорим о том, как их лучше проводить и мониторить, для того, чтобы они сработали максимально эффективно.\n\nРабота официантов в ресторане достаточно однотипна: огромное количество гостей, схожие ситуации и диалоги. Поэтому нет ничего странного в том, что рано или поздно мотивация персонала сильно снижается. На этот случай опытным путём выявлена уже масса способов и методов повышения мотивации. И сегодня мы рассмотрим один из них — конкурс для персонала.\n\n \n\nЭто один самых замечательных и результативных способов разнообразить работу и при этом быстро увеличить продажи. Если нам нужно быстро поднять продажи в ресторане, то руководство заведения первым делом запускает конкурс для всех сотрудников, которые хоть как-то влияют на продажи.\n\nУ любого конкурса для официантов должна быть определена цель. Из самых популярных и востребованных можно выделить:\n\nУвеличение продаж определенных напитков или блюд;\nУвеличение продаж на дополнительных предложениях;\n\nПоэтому первым делом, перед тем как вы начнёте всё веселье, вам нужно понять для чего вы всё это делаете. Вы выбираете слабые продукты для продажи и вкладываете все свои ресурсы, чтобы их подтянуть. Обычно мы их определяем на основе отчетов.\n\n \n\nИнструкция по запуску:\n\n \n\nКак у любого вида мотивации сотрудника, у конкурса тоже есть своя внутренняя последовательность. Нарушая или пропуская один из шагов Вы ставите под удар всю операцию. Поэтому я подготовила для Вас максимально короткую и ёмкую инструкцию, по которой Вам нужно пройти для успеха.\n\n \n\nОпределите тему конкурса. Очень важно, чтобы все сотрудники понимали конечную цель и при этом у всех были одинаковые шансы для победы, иначе уже на старте “слабые” сотрудники уйдут с дистанции, по-умолчанию осознавая отсутствие шансов к победе.\nОпределить время старта и окончания. Как у любого соревнования, у Вас должно быть определенно вплоть до минуты начало и конец конкурса. И никаких переносов или “закончим, когда посчитаем нужным”, это всё только испортит идею и Вашу репутацию управленца.\nОпределить подарок. Казалось бы нет ничего проще, чем придумать подарок, но это не так, особенно когда у Вас уже и так высокие зарплаты и следственно деньги не мотивируют. Помните главное — подарок должен зажигать всех, иначе снова провал.\nСоздать мотивационную доску. Помимо того, что Вы должны разработать таблицу/график, где будете отмечать успехи каждого, так Вы ещё и должны всё это повесить на видном месте (идеально — обеденная зона) и ежедневно отмечать результаты.\nПридать огласке. На каждой пятиминутке или собрании Вам нужно подливать бензин в огонь, чтобы участники постоянно находились в состоянии здоровой конкуренции и верили в свои силы.\n\nЛогичное завершение всего соревнования — это подведение итогов. Рекомендую награждать победителя публично и с большим охватом. Эту шоу-программу Вы делаете, чтобы каждый хотел оказаться в следующий раз на его месте. Ведь конкурс это не разовое мероприятие, а повторяющееся из месяца в месяц.","images":["assets/remaining-courses/guru-25811-42953-0.jpg","assets/remaining-courses/guru-25811-42953-1.jpg"],"links":[{"title":"способов и методов повышения мотивации","url":"https://in-scale.ru/blog/metody-i-sposoby-motivacii.html"},{"title":"увеличить продажи","url":"https://in-scale.ru/blog/uvelichenie-prodazh-plan-s-42-sposobami-i-metodami.html"},{"title":"вида мотивации сотрудника,","url":"https://in-scale.ru/blog/vidy-motivacii-personala.html"},{"title":"Видео к уроку","url":"https://www.youtube.com/embed/_LtZZHB18Kw?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25811%2Flesson%2F42953&aoriginsup=1&vf=1"}],"id":"42953"},{"title":"Постановка Целей для сотрудников","text":"Модель SMART\n\nЦель – это то, к чему стремятся, чего хотят достигнуть; назначение, смысл предпринимаемых действий.\n\nКлассической и одной из наиболее известных моделей постановки целей, прогнозирования изменений и планирования является модель SMART-критерии.\n\nSMART – это аббревиатура, образованная первыми буквами английских слов, в переводе на русский язык обозначающая «умный»:\n\nS (specific) – конкретный\nM (measurable) — измеримый\nA (attainable) — достижимый\nR (realistic) — реалистичный\nT (timebound) – определенный во времени\n\nТаким образом, правильная постановка цели означает, что она должна быть конкретной, измеримой, достижимой, значимой и соотносится с конкретным сроком.\n\nРассмотрим каждый из обозначенных критериев и определим, что подразумевает постановка SMART-целей на практике.\n\nПримеры, какой должна быть постановка целей по SMART.\n\nРассмотрим 10 целей, которые корректно поставлены по СМАРТ и соответствуют всем вышеперечисленным критериям:\n\n﻿\n\nНачать зарабатывать 200 000 рублей ежемесячно на текущем месте работы к 20 июля 2018 года.\nПройти интервью по компетенциям на управляющего одного из ресторанов моей сети в 2019 году.\nСдать экзамен на получение водительского удостоверения категории В до 31 мая 2016 года.\nСделать в ресторане выручку 1000000 в декабре 2018\nПройти бесплатный тренинг «Личностный рост» до 31 августа 2018 года.\nВыучить 100 английских слов за 30 дней.\n\nЧтобы достичь какой-либо цели, важно для начала сформировать намерение. Желательно в письменном виде. Чтобы верно сформулировать цель, примените к своему намерению метод SMART. Таким образом, вы сразу увидите те скрытые проблемы, которые могут помешать вашему намерению исполниться.\n\nФормулировка цели по методу SMART - лучший способ сконцентрироваться на вашем намерении. То есть, вы уже автоматически настроитесь на необходимую волну. Как результат, вы не только придумаете способ, как достичь цель, но и «притянете» все необходимые события, а в некоторых случаях, достигнете целей, ничего для достижения не делая.\n\nПрименяя конкретизацию и способ измерения достижения результата, вы сформируете лучшее понимание того, что вы хотите на самом деле. Такой подход поможет выявить свои цели и избавиться от навязанных.\n\nПроверяя свою цель на реалистичность, вы непременно осознаете и поймете связь этой цели с другими вашими целями, целями близких людей и т.д. SMART-метод применим также к советам от других людей, к любым рекомендациям, предложениям и т.п. (например, на совещании)\n\nКогда целей много, SMART поможет отсеять «плохие» цели и работать только с «хорошими».","images":["assets/remaining-courses/guru-25811-42954-0.jpg","assets/remaining-courses/guru-25811-42954-1.jpg"],"links":[{"title":"Видео к уроку","url":"https://www.youtube.com/embed/2zZh418zaSw?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F25811%2Flesson%2F42954&aoriginsup=1&vf=1"}],"id":"42954"},{"title":"Чек-листы","text":"Чек-листы\n\nМожешь использовать эти чек-листы в своей работе или подготовить свои собственные на их примере.\n\nКЛН официанта\n\nВнешний вид сотрудника зала\n\nОткрытие смены официанта\n\nОткрытие смены бармена\n\nЗакрытие смены бармена\n\nОткрытие заведения\n\nГлавное не забывай заполнять чек-листы ;)","images":["assets/remaining-courses/guru-25811-42955-0.jpg"],"links":[{"title":"КЛН официанта","url":"https://drive.google.com/open?id=1l16OueFvrJS0XJmArlH5xI1aCJ3ODMhV"},{"title":"Внешний вид сотрудника зала","url":"https://drive.google.com/open?id=1ctcLcSXpfTjd-Cl14RZUoWYNxUm8cvkj"},{"title":"Открытие смены официанта","url":"https://drive.google.com/open?id=1A-OIpHtLyBxG1P9wxbkefKLF_4Wg0v3a"},{"title":"Открытие смены бармена","url":"https://drive.google.com/open?id=124CkZ9YIZ5X7eVOfwkv76K_3F0Lc2vgA"},{"title":"Закрытие смены бармена","url":"https://drive.google.com/open?id=1lXjfwt0xkIQjOnN-eXNIzgLgToibsCnW"},{"title":"Открытие заведения","url":"https://drive.google.com/open?id=12NZWhCqdB4_3cUWle2T5fftt0uVKcRte"}],"id":"42955"}],"outline":[{"type":"lesson","title":"Рабочий день менеджера смены.","lessonIndex":0},{"type":"test","title":"Тест к Уроку 1. Рабочий день администратора."},{"type":"lesson","title":"Делаем рутинное интересным: Проведение пятиминуток","lessonIndex":1},{"type":"test","title":"Тест к уроку 2. Пятиминутки."},{"type":"lesson","title":"Менеджер - младший HR в заведении","lessonIndex":2},{"type":"test","title":"Тест к уроку 4. HR"},{"type":"lesson","title":"Коммуникация с сотрудниками на смене.","lessonIndex":3},{"type":"test","title":"Тест к уроку 5. Коммуникация на смене и обратная связь."},{"type":"lesson","title":"Роль менеджера в построении продаж в ресторане","lessonIndex":4},{"type":"test","title":"Тест к уроку 6. Роль менеджера в построении продажи"},{"type":"lesson","title":"Лучшая практика для выполнения плана по продажам.","lessonIndex":5},{"type":"test","title":"Тест к уроку 7. Лучшая практика для выполнения плана по продажам"},{"type":"lesson","title":"Постановка Целей для сотрудников","lessonIndex":6},{"type":"test","title":"Тест к уроку 8. Постановка целей."},{"type":"lesson","title":"Чек-листы","lessonIndex":7}],"testIds":["56097","56098","56099","56100","56101","56102","56103"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
commit;
